CIRC = '①②③④⑤'


def ln(s, cls=''):
    return f'<div class="ln{(" " + cls) if cls else ""}">{s}</div>'


def bogi(html, title='<보기>'):
    return {'type': 'bogi', 'title': title, 'html': html}


def q(src, stem, blocks, choices, **kw):
    d = {'part': P, 'src': src, 'stem': stem, 'blocks': blocks, 'choices': choices}
    d.update(kw)
    return d


def ctab(head, rows):
    C = 'style="text-align:center;padding:.5mm 6mm"'
    return ('<table class="ht chtab"><tr><td></td>' + ''.join(f'<td {C}>{h}</td>' for h in head) + '</tr>'
            + ''.join(f'<tr><td>{CIRC[i]}</td>' + ''.join(f'<td {C}>{w}</td>' for w in r) + '</tr>' for i, r in enumerate(rows)) + '</table>')


def pairs(items):
    """[(기호, 문장1, 문장2)] → 선지마다 기호 + 두 문장 괄호 묶음"""
    return [f'<span class="lab">{lab}</span><span class="dlg brc">{a}<br>{b}</span>' for lab, a, b in items]


